"""Generates ../pydecimal_table.go: the str.isdecimal() characters of the
Python running this script (CPython 3.11, Unicode 14), as starts of runs of
ten consecutive code points with the decimal values 0..9.

    rt -- bash -lc 'cd server/internal/agents/monitor && ~/cf-test/.venv/bin/python testdata/gen_decimal.py > pydecimal_table.go'
"""
import sys
import unicodedata

starts = []
cp = 0
while cp <= sys.maxunicode:
    if chr(cp).isdecimal():
        assert unicodedata.decimal(chr(cp)) == 0, hex(cp)
        for k in range(10):
            assert chr(cp + k).isdecimal() and unicodedata.decimal(chr(cp + k)) == k, hex(cp + k)
        starts.append(cp)
        cp += 10
    else:
        cp += 1
print('// Code generated by testdata/gen_decimal.py (Python %s, Unicode %s); DO NOT EDIT.'
      % (sys.version.split()[0], unicodedata.unidata_version))
print()
print('package monitor')
print()
print('// pyDecimalStarts are the first code points of the runs of ten decimal')
print('// digits (str.isdecimal, values 0..9) of CPython 3.11.')
print('var pyDecimalStarts = []rune{')
for i in range(0, len(starts), 8):
    print('\t' + ' '.join('0x%X,' % s for s in starts[i:i + 8]))
print('}')
